    name: { de: "Mellah-Slimane-Brücke", hu: "Mellah Slimane-híd", ro: "Podul Mellah Slimane", en: "Mellah Slimane Bridge"},
    image: "/poi-images/mellah-slimane-bridge-landmarks-v2.webp",
    description: {
      de: "Eine weitere berühmte Brücke in Constantine, die für ihre elegante Konstruktion und die Aussicht auf die Altstadt bekannt ist.",
      hu: "A Mellah Slimane-híd egy keskeny gyalogos függőhíd, amely a szurdok felett vezet Constantine-ban. A tériszonnyal nem küzdőknek lélegzetelállító kilátást nyújt a mélyben futó folyóra.",
      ro: "Podul Mellah Slimane este un pod suspendat pietonal îngust care traversează defileul din Constantine. Oferă o priveliște uluitoare asupra râului de jos pentru cei fără frică de înălțime.",
      en: "The Mellah Slimane Bridge is a narrow pedestrian suspension bridge crossing the gorge in Constantine. It offers a breathtaking view of the river far below for those not afraid of heights.",
      es: "Otro puente famoso en Constantina, conocido por su elegante construcción y las vistas del casco antiguo.",
      pt: "Outra ponte famosa em Constantina, conhecida pela sua construção elegante e pelas vistas da cidade velha.",
      fr: "Un autre pont célèbre de Constantine, réputé pour son architecture élégante et ses vues sur la vieille ville.",
    },
    facts: {
      de: ["Fußgängerbrücke", "Konstruktion aus Stahl", "Verbindet Stadtteile"],
      hu: ["1925-ben adták át", "Csak gyalogosok számára", "125 méter hosszú", "Séta közben enyhén inog"],
      ro: ["Deschis în 1925", "Doar pentru pietoni", "125 de metri lungime", "Se clatină ușor la mers"],
      en: ["Opened in 1925", "Pedestrians only", "125 meters long", "Sways slightly when walking"],
      es: ["Puente peatonal", "Construcción de acero", "Conecta barrios"],
      pt: ["Ponte pedonal", "Construção em aço", "Liga bairros da cidade"],
      fr: ["Passerelle piétonne", "Structure en acier", "Relie les quartiers"],
    },
    descriptionAdvanced: {
      de: "Die Mellah-Slimane-Brücke in Constantine ist eine markante Fußgängerhängebrücke, die das Stadtzentrum direkt mit dem tiefer gelegenen Viertel am Bahnhof verbindet. Sie wurde zwischen 1917 und 1925 erbaut und ist nach einem Helden des algerischen Befreiungskrieges benannt. Die Brücke überspannt die Rhumel-Schlucht in einer Höhe von etwa 100 Metern und ist für ihre filigrane Eisenkonstruktion bekannt. Ein besonderes Merkmal ist der vertikale Aufzug an einem Ende der Brücke, der Fußgängern den beschwerlichen Aufstieg von der Schlucht in die Oberstadt erspart. Trotz ihrer geringeren Breite im Vergleich zu den anderen Brücken der Stadt ist sie eine der am stärksten frequentierten Übergänge für die lokale Bevölkerung. Während man die Brücke überquert, spürt man oft die leichten Schwingungen der Konstruktion, was den Weg über den Abgrund zu einem besonderen Erlebnis macht. Von der Mitte aus hat man einen faszinierenden Blick auf die Kaskaden des Rhumel und die historischen Gerbereien, die sich tief unten an den Felswänden befinden.",
      hu: "A Mellah Slimane-híd Constantine egyik legfontosabb gyalogos összeköttetése, amely a vasútállomás környékét köti össze a sziklára épült óvárossal. Az 1917 és 1925 között épült függőhíd 125 méter hosszú és körülbelül 100 méterrel magasodik a Rhumel-folyó medre fölé. A híd különlegessége a nyugati végén található hatalmas köztéri lift, amely lehetővé teszi a gyalogosok számára a nagy szintkülönbség gyors leküzdését. Az építmény kecses vasszerkezete és keskeny mivolta ellenére óriási forgalmat bonyolít le nap mint nap, mivel ez a legrövidebb út a város két fontos pontja között. Nevét egy algériai szabadságharcostól kapta, korábban Perrégaux-hídnak hívták. A hídon sétálva közvetlen közelről szemlélhetők a kanyon meredek falai és a mélyben zubogó vízesések. Bár kevésbé monumentális, mint a Sidi M'Cid-híd, technikai megoldásai és közösségi szerepe miatt nélkülözhetetlen része Constantine városképének.",
      ro: "Podul Mellah Slimane este o pasarelă pietonală suspendată din Constantine, care oferă o conexiune directă între centrul vechi și zona gării feroviare. Construit între anii 1917 și 1925, podul are o lungime de 125 de metri și se ridică la 100 de metri deasupra albiei râului Rhumel. O caracteristică unică a acestui pod este ascensorul public situat la unul dintre capete, care facilitează accesul cetățenilor între platformele de înălțime diferite ale orașului. Cunoscut anterior sub numele de Podul Perrégaux, acesta a fost redenumit după independență în onoarea unui martir local. Structura sa ușoară din fier este proiectată să reziste la vânturile puternice din defileu, dar oferă pietonilor o senzație ușoară de balans în timpul traversării. Vederea de pe pod cuprinde grădinile suspendate și stâncile calcaroase sculptate de eroziunea seculară a apei. Este un punct de observație ideal pentru a vedea cum orașul s-a adaptat la un relief extrem de accidentat, transformând obstacolele naturale în puncte de atracție arhitecturală.",
      en: "The Mellah Slimane Bridge is a vital pedestrian suspension bridge in Constantine, linking the railway station district with the historic heart of the city. Constructed between 1917 and 1925, it spans 125 meters across the Rhumel gorge at a height of roughly 100 meters. A distinctive engineering feature is the large public elevator at the western end, which helps pedestrians navigate the steep vertical distance between the upper and lower parts of the city. Originally named the Perrégaux Bridge, it was renamed after Mellah Slimane, a hero of the Algerian War of Independence. Despite its narrow path, the bridge is constantly buzzing with locals, serving as the most direct route for commuters. Crossing the bridge offers a thrilling experience as the metal structure slightly sways over the abyss, providing stunning views of the waterfalls and the old tanneries below. It stands as a remarkable example of how early 20th-century engineering solved the challenges of Constantine's rugged topography while creating a lasting urban landmark.",
      es: "El puente Mellah Slimane es un elemento notable de la geografía y cultura argelinas. Es un estrecho puente colgante peatonal que cruza el desfiladero en Constantina. Ofrece a quienes no temen a las alturas una vista impresionante del río en lo profundo. Inaugurado en 1925. Solo para peatones. Longitud de 125 metros. Este hito forma parte del patrimonio cultural de Argelia y refleja influencias bereberes, árabes y mediterráneas. Como muchos lugares importantes en Argelia, este sitio une la herencia bereber con influencias mediterráneas y saharauis. Así, este lugar contribuye al perfil versátil de Argelia.",
      pt: "A ponte Mellah Slimane é um elemento notável da geografia e cultura argelinas. É uma ponte suspensa pedonal estreita que atravessa o desfiladeiro em Constantina. Oferece a quem não tem vertigens uma vista deslumbrante sobre o rio lá em baixo. Inaugurada em 1925. Apenas para peões. Comprimento de 125 metros. Este marco faz parte do património cultural da Argélia e reflete influências berberes, árabes e mediterrâneas. Como muitos lugares importantes na Argélia, este sítio une a herança berbere com influências mediterrâneas e saarianas. Assim, este lugar contribui para o perfil versátil da Argélia.",
      fr: "Le pont Mellah Slimane est un élément remarquable de la géographie et de la culture algériennes. C'est une passerelle suspendue étroite qui enjambe les gorges à Constantine. Il offre aux personnes ne souffrant pas de vertige une vue imprenable sur la rivière en contrebas. Inauguré en 1925. Réservé aux piétons. Long de 125 mètres. Ce monument appartient au patrimoine culturel de l'Algérie et reflète les influences berbères, arabes et méditerranéennes. Comme de nombreux sites importants en Algérie, ce lieu unit l'héritage berbère aux influences méditerranéennes et sahariennes. Ainsi, ce lieu contribue au profil diversifié de l'Algérie.",
    },
