      de: ["Erbaut zwischen 1917 und 1925", "Fußgängerhängebrücke mit einer Länge von 125 Metern", "Höhe von ca. 100 Metern über dem Rhumel", "Verfügt über einen öffentlichen Aufzug am westlichen Ende", "Früherer Name war Passerelle Perrégaux", "Benannt nach einem algerischen Unabhängigkeitskämpfer"],
