      es: ["Inaugurado en 1925.", "Solo para peatones.", "Longitud de 125 metros.", "Se balancea ligeramente al caminar.", "El puente Mellah Slimane es una estrecha pasarela colgante en Constantina. Ofrece una vista espectacular del río Rhumel a gran profundidad.", "Situado en el territorio de la República Argelina Democrática y Popular.", "Desempeña un papel en la identidad local de la región."],
      pt: ["Inaugurada em 1925.", "Apenas para peões.", "Comprimento de 125 metros.", "Balança ligeiramente ao caminhar.", "A ponte Mellah Slimane é uma ponte suspensa pedonal estreita em Constantina. Oferece uma vista deslumbrante sobre o rio lá em baixo.", "Localizada no território da República Argelina Democrática e Popular.", "Desempenha um papel na identidade local da região."],
      fr: ["Inauguré en 1925.", "Réservé aux piétons.", "Long de 125 mètres.", "Oscille légèrement en marchant.", "Le pont Mellah Slimane est une passerelle suspendue étroite située à Constantine. Il offre une vue imprenable sur les gorges et la rivière en contrebas.", "Située sur le territoire de la République Algérienne Démocratique et Populaire.", "Joue un rôle dans l'identité locale de la région."],
