    facts: {
      de: ["Wallfahrtskapelle", "Blick auf Oran", "Historische Festung"],
      hu: ["Orán", "Kápolna", "Panoráma"],
      ro: ["Construită în 1850", "Recunoștință pentru sfârșitul holerei", "Statuia Mariei pe cupolă", "Loc de pelerinaj"],
      en: ["Built in 1850", "Gratitude for cholera end", "Statue of Mary on the dome", "Place of pilgrimage"],
      es: ["Capilla de peregrinación", "Vista sobre Orán", "Fortaleza histórica"],
      pt: ["Capela de peregrinação", "Vista sobre Oran", "Fortaleza histórica"],
      fr: ["Chapelle de pèlerinage", "Vue sur Oran", "Forteresse historique"],
    },
    descriptionAdvanced: {
      de: "Die Chapelle Santa Cruz befindet sich auf dem Gipfel des Berges Murdjadjo in Oran und ist eines der markantesten religiösen Bauwerke Algeriens. Sie wurde im Jahr 1850 errichtet, nachdem eine verheerende Cholera-Epidemie die Stadt heimgesucht hatte, und dient seitdem als Ort des Dankes und der Andacht. Die Kapelle liegt auf einer Höhe von etwa 400 Metern über dem Meeresspiegel und bietet einen weitreichenden Blick über die Bucht von Oran und den Hafen Mers El Kébir. Architektonisch ist das Gebäude im romanisch-byzantinischen Stil gehalten und wird von einer großen Marienstatue gekrönt, die eine Kopie der Notre-Dame de la Garde in Marseille darstellt. Unterhalb der Kapelle liegen die massiven Mauern des Fort Santa Cruz, das ursprünglich im 16. Jahrhundert von den Spaniern erbaut wurde. Jedes Jahr am Christi Himmelfahrtstag finden Wallfahrten zu diesem Ort statt, was seine anhaltende kulturelle und religiöse Bedeutung unterstreicht. Heute ist die Stätte ein Symbol für die wechselvolle koloniale Geschichte der Region und ein wichtiger Anziehungspunkt für Touristen.",
      hu: "A Chapelle Santa Cruz Orán városának egyik legjelentősebb vallási és történelmi emlékműve, amely a Murdjadjo-hegy csúcsán, mintegy 400 méteres tengerszint feletti magasságban található. A kápolnát 1850-ben építették egy pusztító kolerajárvány után, amely több ezer áldozatot követelt a városban; az épületet Szűz Mária tiszteletére szentelték hálából a járvány megszűnéséért. Az építészeti stílus a romanika és a bizánci formavilág elemeit ötvözi, a tornyán pedig egy monumentális Mária-szobor látható, amely a marseille-i Notre-Dame de la Garde szobrának másolata. A kápolna közvetlen szomszédságában fekszik a Santa Cruz-erőd, amelyet még a spanyolok emeltek a 16. században stratégiai védelmi célokból. A helyszínről lenyűgöző panoráma nyílik Orán öblére és a Földközi-tengerre, emellett fontos zarándokhelyként is szolgál az algériai katolikus közösség számára. A 20. századi restaurálások során megőrizték eredeti jellegét, így ma is a francia gyarmati építészet egyik kiemelkedő példája Észak-Afrikában.",
      ro: "Chapelle Santa Cruz este un monument religios emblematic situat pe culmea Muntelui Murdjadjo din Oran, oferind o perspectivă panoramică asupra orașului și a Mării Mediterane. Edificiul a fost construit în anul 1850 ca urmare a unei epidemii devastatoare de holeră care a decimat populația locală, fiind dedicat Fecioarei Maria în semn de recunoștință pentru sfârșitul molimei. Arhitectura capelei îmbină stilul romanic cu cel bizantin, fiind ușor de recunoscut după statuia monumentală a Fecioarei Maria, o replică a celei de la Notre-Dame de la Garde din Marsilia. Amplasată la o altitudine de aproximativ 400 de metri, capela se află în imediata apropiere a fortăreței Santa Cruz, construită inițial de spanioli în secolul al XVI-lea. Locul a devenit în timp un important centru de pelerinaj, în special pentru comunitatea creștină, păstrându-și relevanța culturală și după independența Algeriei. În prezent, situl este protejat ca monument istoric și reprezintă un punct de atracție major pentru vizitatorii regiunii.",
      en: "The Chapelle Santa Cruz is a significant religious monument located on the crest of Mount Murdjadjo in Oran, Algeria. Built in 1850 following a devastating cholera epidemic that claimed thousands of lives, the chapel was dedicated to the Virgin Mary as a symbol of gratitude for the end of the plague. Perched at an altitude of approximately 400 meters, it offers a commanding view of the city of Oran and the Mediterranean Sea. The architecture reflects a Romanesque-Byzantine style, and the site includes a massive statue of the Virgin Mary, a replica of the one in Marseille. Throughout history, it has served as a place of pilgrimage and a landmark of French colonial heritage in North Africa. Today, it remains one of Oran's most visited sites, representing a blend of spiritual significance and historical memory. The surrounding fortifications of the Fort Santa Cruz, built by the Spanish in the 16th century, further enhance the site's historical depth and architectural complexity.",
      es: "La capilla de Santa Cruz es un elemento notable de la geografía y cultura argelina. Se encuentra en Orán, cerca de la fortaleza del mismo nombre. Fue construida en el siglo XIX como agradecimiento por el fin de una epidemia de cólera y está coronada por una estatua de la Virgen María. Construida en 1850. Agradecimiento por el fin del cólera. Estatua de María en la cúpula. Este monumento es parte del patrimonio cultural de Argelia y refleja influencias bereberes, árabes y mediterráneas. Como muchos lugares importantes en Argelia, este sitio combina el legado bereber con influencias mediterráneas y saharianas. Así, este lugar contribuye al perfil versátil de Argelia.",
      pt: "A capela de Santa Cruz é um elemento notável da geografia e cultura argelina. Situa-se em Oran, perto da fortaleza com o mesmo nome. Foi construída no século XIX em agradecimento pelo fim de uma epidemia de cólera e é coroada por uma estátua da Virgem Maria. Construída em 1850. Agradecimento pelo fim do cólera. Estátua de Maria na cúpula. Este marco faz parte do patrimônio cultural da Argélia e reflete influências berberes, árabes e mediterrâneas. Como muitos lugares importantes na Argélia, este local combina a herança berbere com influências mediterrâneas e saarianas. Assim, este lugar contribui para o perfil versátil da Argélia.",
      fr: "La chapelle Santa Cruz est un élément remarquable de la géographie et de la culture algériennes. Elle est située à Oran, à proximité de la forteresse du même nom. Érigée au XIXe siècle en action de grâce pour la fin d'une épidémie de choléra, elle est surmontée d'une statue de la Vierge Marie. Construite en 1850. Remerciement pour la fin du choléra. Statue de Marie sur le dôme. Ce monument fait partie du patrimoine culturel de l'Algérie et reflète des influences berbères, arabes et méditerranéennes. Comme beaucoup de sites importants en Algérie, ce lieu allie héritage berbère, influences méditerranéennes et sahariennes. Ce site contribue ainsi au profil diversifié de l'Algérie.",
    },
