      de: ["Die Kapelle wurde 1850 nach einer Cholera-Epidemie erbaut.", "Sie liegt auf dem Gipfel des Murdjadjo-Berges in 400 Metern Höhe.", "Die Marienstatue ist eine Kopie der Notre-Dame de la Garde aus Marseille.", "Das Gebäude verbindet romanische und byzantinische Baustile.", "Unterhalb der Kapelle befindet sich eine spanische Festung aus dem 16. Jahrhundert.", "Jährlich findet an Christi Himmelfahrt eine traditionelle Wallfahrt statt."],
