      ro: ["Capela a fost construită în 1850 în urma unei epidemii de holeră.", "Este situată pe muntele Murdjadjo, la o altitudine de 400 de metri.", "Statuia Fecioarei Maria este o replică a celei din Marsilia.", "Stilul arhitectural este o combinație de romanic și bizantin.", "Lângă capelă se află fortul spaniol construit în secolul al XVI-lea.", "Situl este unul dintre cele mai vizitate puncte turistice din Oran."],
      en: ["The chapel was built in 1850 following a major cholera outbreak.", "It is situated on Mount Murdjadjo at an elevation of 400 meters.", "The Virgin Mary statue is a replica of the one in Marseille, France.", "The architectural design incorporates Romanesque and Byzantine styles.", "It is located directly below a 16th-century Spanish fortress.", "The site serves as a prominent pilgrimage destination in North Africa."],
      es: ["Construida en 1850.", "Agradecimiento por el fin del cólera.", "Estatua de María en la cúpula.", "Lugar de peregrinación.", "La capilla de Santa Cruz se encuentra en Orán, cerca de la fortaleza del mismo nombre. Fue construida en el siglo XIX como agradecimiento por el fin de una epidemia de cólera y está coronada por una estatua de la Virgen María.", "Ubicada en el territorio de la República Argelina Democrática y Popular.", "Desempeña un papel en la identidad local de la región."],
      pt: ["Construída em 1850.", "Agradecimento pelo fim do cólera.", "Estátua de Maria na cúpula.", "Local de peregrinação.", "A capela de Santa Cruz situa-se em Oran, perto da fortaleza com o mesmo nome. Foi construída no século XIX em agradecimento pelo fim de uma epidemia de cólera e é coroada por uma estátua da Virgem Maria.", "Localizada no território da República Argelina Democrática e Popular.", "Desempenha um papel na identidade local da região."],
      fr: ["Construite en 1850.", "Action de grâce pour la fin du choléra.", "Statue de Marie sur le dôme.", "Lieu de pèlerinage.", "La chapelle Santa Cruz est située à Oran, à proximité de la forteresse du même nom. Elle a été érigée au XIXe siècle pour remercier de la fin d'une épidémie de choléra et est surmontée d'une statue de la Vierge.", "Située sur le territoire de la République Algérienne Démocratique et Populaire.", "Joue un rôle dans l'identité locale de la région."],
