    description: {
      de: "Bab El Khemis ist ein antikes Stadttor in Tlemcen, das ursprünglich Teil der Stadtmauern war. Heute steht es als majestätischer Bogen und historisches Wahrzeichen für die marokkanisch-andalusische Architektur.",
      hu: "Egy történelmi városkapu Tlemcenben, amely a középkori védelmi rendszer része volt.",
      ro: "Bab El Khemis este o veche poartă a orașului din Tlemcen care făcea parte inițial din zidurile orașului. Astăzi stă ca un arc maiestuos și un reper istoric al arhitecturii marocano-andaluze.",
      en: "Bab El Khemis is an ancient city gate in Tlemcen that was originally part of the city walls. Today it stands as a majestic arch and a historic landmark of Moroccan-Andalusian architecture.",
      es: "Bab El Khemis es una antigua puerta de la ciudad en Tremecén que originalmente formaba parte de las murallas. Hoy se erige como un arco majestuoso y símbolo de la arquitectura marroquí-andalusí.",
      pt: "Bab El Khemis é uma antiga porta da cidade em Tremecém, que originalmente fazia parte das muralhas. Hoje ergue-se como um arco majestoso e marco histórico da arquitetura marroquina-andaluza.",
      fr: "Bab El Khemis est une ancienne porte de la ville de Tlemcen, qui faisait initialement partie des remparts. Aujourd'hui, elle se dresse comme une arche majestueuse, emblème de l'architecture maroco-andalouse.",
    },
