    coords: [6.6111, 36.3639],
    name: { de: "Sidi-Rached-Brücke", hu: "Sidi Rached-híd", ro: "Podul Sidi Rached", en: "Sidi Rached Bridge"},
    image: "/poi-images/sidi-rached-bridge-landmarks-v2.webp",
    description: {
      de: "Die Sidi-Rached-Brücke ist ein beeindruckendes Viadukt in Constantine, das zu den größten Steinbogenbrücken der Welt gehört.",
      hu: "Constantine ikonikus hídja, amely a város mély kanyonjai felett ível át.",
      ro: "Podul Sidi Rached din Constantine este o realizare inginerească remarcabilă peste defileul râului Rhummel.",
      en: "The Sidi Rached Bridge in Constantine is a massive stone viaduct connecting the neighborhoods across the deep gorge. At the time of its construction, it was the highest stone bridge in the world.",
      es: "El puente Sidi Rached es un impresionante viaducto en Constantina que se cuenta entre los puentes de arco de piedra más grandes del mundo.",
      pt: "A ponte Sidi Rached é um impressionante viaduto em Constantina, estando entre as maiores pontes de arco de pedra do mundo.",
      fr: "Le pont Sidi Rached est un viaduc impressionnant de Constantine, figurant parmi les plus grands ponts en maçonnerie du monde.",
    },
    facts: {
      de: ["Steinbogen-Viadukt", "Meisterwerk der Ingenieurskunst", "Wahrzeichen von Constantine"],
      hu: ["Constantine", "Ikonikus híd", "Kanyon"],
      ro: ["Pod arcuit", "Constantine", "Inginerie spectaculoasă"],
      en: ["Opened in 1912", "447 meters long", "27 arches", "Stone viaduct"],
      es: ["Viaducto de arcos de piedra", "Obra maestra de la ingeniería", "Hito de Constantina"],
      pt: ["Viaduto de arcos de pedra", "Obra-prima da engenharia", "Marco de Constantina"],
      fr: ["Viaduc en maçonnerie", "Chef-d'œuvre d'ingénierie", "Emblème de Constantine"],
    },
    descriptionAdvanced: {
      de: "Die Sidi-Rached-Brücke in Constantine ist ein technisches Meisterwerk des frühen 20. Jahrhunderts und eines der markantesten Wahrzeichen der „Stadt der Brücken“. Erbaut zwischen 1908 und 1912 unter der Leitung des französischen Ingenieurs Paul Séjourné, war sie zum Zeitpunkt ihrer Fertigstellung die höchste Steinbogenbrücke der Welt. Das Viadukt überspannt den tiefen Abgrund des Rhumel-Flusses und verbindet das Stadtzentrum mit dem Viertel Sidi Rached sowie dem Bahnhof. Die Brücke beeindruckt durch ihre gewaltige Länge von 447 Metern und eine maximale Höhe von 105 Metern über dem Flussbett. Die Konstruktion besteht aus 27 Bögen unterschiedlicher Größe, wobei der Hauptbogen eine Spannweite von 70 Metern aufweist. Die Verwendung von lokalem Stein verleiht der Brücke eine ästhetische Harmonie mit den umliegenden Felsformationen der Schlucht. Trotz ihres Alters trägt die Brücke auch heute noch einen bedeutenden Teil des städtischen Verkehrs und bietet Fußgängern einen atemberaubenden Blick in die Tiefe. Die Sidi-Rached-Brücke symbolisiert die außergewöhnliche Ingenieurskunst, die notwendig war, um die dramatische Topographie Constantines zu bezwingen. Sie ist ein unverzichtbares Ziel für Architekturinteressierte und Fotografen aus aller Welt.",
      hu: "A konstantini Sidi Rached híd a 20. század eleji mérnöki tudomány mesterműve, és a „Hidak városa” egyik legjellegzetesebb látnivalója. 1908 és 1912 között épült Paul Séjourné francia mérnök vezetésével, és elkészültekor a világ legmagasabb kőívhídja volt. A viadukt a Rhumel-folyó mély szakadékát íveli át, összekötve a városközpontot a Sidi Rached negyeddel és a vasútállomással. A híd lenyűgöző, 447 méteres hosszúságával és a folyómeder feletti 105 méteres maximális magasságával vívta ki elismerését. A szerkezet 27 különböző méretű ívből áll, amelyek közül a főív fesztávolsága 70 méter. A helyi kő használata esztétikai összhangot teremt a híd és a kanyon környező sziklaalakzatai között. Kora ellenére a híd ma is a városi forgalom jelentős részét bonyolítja le, a gyalogosoknak pedig lélegzetelállító kilátást nyújt a mélységbe. A Sidi Rached híd azt a rendkívüli mérnöki teljesítményt jelképezi, amelyre szükség volt Konstantin drámai domborzatának legyőzéséhez. Az építészet iránt érdeklődők és a fotósok számára világszerte kihagyhatatlan úti cél.",
      ro: "Podul Sidi Rached din Constantine este o capodoperă inginerească de la începutul secolului XX și unul dintre cele mai emblematice repere ale „Orașului Podurilor”. Construit între 1908 și 1912 sub coordonarea inginerului francez Paul Séjourné, acesta a fost, la momentul finalizării sale, cel mai înalt pod cu arc de piatră din lume. Viaductul traversează abisul adânc al râului Rhumel, conectând centrul orașului de cartierul Sidi Rached și de gară. Podul impresionează prin lungimea sa vastă de 447 de metri și o înălțime maximă de 105 metri deasupra albiei râului. Construcția este formată din 27 de arcuri de dimensiuni diferite, arcul principal având o deschidere de 70 de metri. Utilizarea pietrei locale conferă podului o armonie estetică cu formațiunile stâncoase înconjurătoare ale canionului. În ciuda vechimii sale, podul susține și astăzi o parte semnificativă a traficului urban și oferă pietonilor o vedere spectaculoasă asupra hăului de dedesubt. Podul Sidi Rached simbolizează ingeniozitatea extraordinară necesară pentru a cuceri topografia dramatică a orașului Constantine. Este o destinație esențială pentru pasionații de arhitectură și fotografii din întreaga lume.",
      en: "The Sidi Rached Bridge in Constantine is an engineering masterpiece of the early 20th century and one of the most distinctive landmarks of the 'City of Bridges.' Built between 1908 and 1912 under the direction of French engineer Paul Séjourné, it was the highest stone arch bridge in the world at the time of its completion. The viaduct spans the deep gorge of the Rhumel River, connecting the city center with the Sidi Rached district and the railway station. The bridge impresses with its vast length of 447 meters and a maximum height of 105 meters above the riverbed. The construction consists of 27 arches of various sizes, with the main arch having a span of 70 meters. The use of local stone provides the bridge with aesthetic harmony with the surrounding rock formations of the canyon. Despite its age, the bridge still carries a significant portion of the city's traffic today and offers pedestrians a breathtaking view into the depths below. The Sidi Rached Bridge symbolizes the extraordinary engineering skill required to conquer the dramatic topography of Constantine. It is an essential destination for architecture enthusiasts and photographers from around the globe.",
      es: "El Puente Sidi Rached es un elemento notable de la geografía y cultura argelina. Es un viaducto de piedra masivo que conecta los barrios sobre el profundo desfiladero. En el momento de su construcción, era el puente de piedra más alto del mundo. Inaugurado en 1912. 447 metros de largo. 27 arcos. Este hito forma parte del patrimonio cultural de Argelia y refleja influencias bereberes y mediterráneas. Como muchos lugares significativos del país, combina herencia histórica con ingeniería monumental.",
      pt: "A Ponte Sidi Rached é um elemento notável da geografia e cultura argelina. É um viaduto de pedra maciço que liga os bairros da cidade sobre o profundo desfiladeiro. Na altura da sua construção, era a ponte de pedra mais alta do mundo. Inaugurada em 1912. 447 metros de comprimento. 27 arcos. Este marco faz parte do património cultural da Argélia e reflete influências berberes, árabes e mediterrâneas. Une a herança berbere com influências mediterrâneas e saarianas.",
      fr: "Le pont Sidi Rached est un élément remarquable de la géographie et de la culture algériennes. Ce viaduc massif en pierre relie les quartiers de la ville au-dessus des gorges profondes. À sa construction, c'était le plus haut pont en pierre du monde. Ouvert en 1912. 447 mètres de long. 27 arches. Ce monument fait partie du patrimoine culturel de l'Algérie et reflète des influences berbères, arabes et méditerranéennes.",
    },
