      de: ["Die Brücke wurde zwischen 1908 und 1912 erbaut.", "Sie hat eine Gesamtlänge von 447 Metern.", "An ihrem höchsten Punkt ragt sie 105 Meter über den Fluss Rhumel.", "Die Brücke besteht aus insgesamt 27 Steinbögen.", "Der Hauptbogen hat eine Spannweite von exakt 70 Metern.", "Sie wurde vom berühmten Ingenieur Paul Séjourné entworfen."],
