      en: ["The bridge was constructed between 1908 and 1912.", "It has a total length of 447 meters.", "At its highest point, it stands 105 meters above the Rhumel River.", "The bridge consists of a total of 27 stone arches.", "The main arch has a span of exactly 70 meters.", "It was designed by the famous engineer Paul Séjourné."],
      es: ["Inaugurado en 1912.", "447 metros de largo.", "27 arcos.", "Viaducto de piedra.", "El Puente Sidi Rached conecta los distritos de la ciudad sobre un profundo abismo, siendo un hito histórico de la ingeniería.", "Situado en el territorio de la República Argelina Democrática y Popular.", "Desempeña un papel en la identidad local de la región."],
      pt: ["Inaugurada em 1912.", "447 metros de comprimento.", "27 arcos.", "Viaduto de pedra.", "A Ponte Sidi Rached liga os distritos da cidade sobre um abismo profundo, sendo um marco histórico da engenharia.", "Localizada no território da República Argelina Democrática e Popular.", "Desempenha um papel na identidade local da região."],
      fr: ["Ouvert en 1912.", "447 mètres de long.", "27 arches.", "Viaduc en pierre.", "Le pont Sidi Rached relie les quartiers de la ville au-dessus d'un abîme profond, monument historique de l'ingénierie.", "Situé sur le territoire de la République Algérienne Démocratique et Populaire.", "Joue un rôle dans l'identité locale de la région."],
